SELECT b.Fname, b.Lname, m.Lname AS Boss
FROM Employee b
LEFT JOIN Employee m ON b.Super_ssn = m.Ssn;

SELECT b.Fname, b.Lname
FROM Employee b
WHERE NOT EXISTS (SELECT 1 FROM Dependent l WHERE l.Essn = b.Ssn);

SELECT Fname, Lname
FROM Employee
WHERE Address LIKE '%Houston%';

SELECT b.Fname, b.Salary
FROM Employee b
WHERE b.Salary > ALL (SELECT c.Salary FROM Employee c WHERE c.Dno = b.Dno);

UPDATE Employee
SET Salary = Salary * 1.10
WHERE Dno = (SELECT Dnumber FROM Department WHERE Dname = 'Research');

SELECT b.Ssn FROM Employee b INNER JOIN Works_On l ON b.Ssn = l.Essn INNER JOIN Project c ON l.Pno = c.Pnumber WHERE c.Pnumber = 1
EXCEPT
SELECT b.Ssn FROM Employee b INNER JOIN Works_On l ON b.Ssn = l.Essn INNER JOIN Project c ON l.Pno = c.Pnumber WHERE c.Pnumber = 2;
